H=W=19
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
markers={(2,6),(3,5),(3,7),(3,13),(4,6),(4,12),(4,14),(5,13),(9,8),(10,7),(10,9),(11,8),(11,14),(12,13),(12,15),(13,3),(13,14),(14,2),(14,4),(15,3)}
# Identify each center's own arms via cross coordinates
own={p:{(p[0]-1,p[1]),(p[0]+1,p[1]),(p[0],p[1]-1),(p[0],p[1]+1)} & markers for p in centers}
g=[[0]*W for _ in range(H)]
for r,c in markers:g[r][c]=3
# rays: include center, stop before first marker belonging to another object. preserve markers
for (r,c),color in centers.items():
 for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
  rr,cc=r,c
  while 0<=rr<H and 0<=cc<W:
   if (rr,cc) in markers and (rr,cc) not in own[(r,c)]: break
   if g[rr][cc]!=3:g[rr][cc]=color
   rr+=dr;cc+=dc
for row in g:print(' '.join(map(str,row)))
print('own',own)
